* { box-sizing: border-box; }
:root { color-scheme: light; --ink: #173b37; --muted: #71827b; --cream: #faf8f0; --green: #247b61; --mint: #d9eee2; --coral: #df765b; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 24px 16px; background: #102d2b; color: var(--ink); font: 16px/1.45 system-ui, sans-serif; }
.booking-card { width: min(100%, 520px); padding: 26px clamp(18px, 5vw, 34px) 20px; border: 1px solid #d8e1d6; border-radius: 22px; background: var(--cream); box-shadow: 0 24px 70px #071c1b88; }
.topbar { display: flex; align-items: center; gap: 10px; color: var(--ink); font-size: 13px; font-weight: 800; letter-spacing: .12em; }
.brand-mark { display: grid; width: 32px; height: 32px; place-items: center; border-radius: 9px; background: var(--green); color: white; font-size: 18px; }
.route-tag { margin-left: auto; padding: 6px 9px; border-radius: 999px; background: #e9ede3; color: #506760; font-size: 11px; letter-spacing: .06em; }
.intro { margin: 28px 0 20px; }
.eyebrow { margin: 0 0 5px; color: var(--green); font-size: 12px; font-weight: 800; letter-spacing: .14em; }
h1 { margin: 0; font-size: clamp(29px, 7vw, 38px); line-height: 1.12; letter-spacing: -.04em; }
.subhead { margin: 8px 0 0; color: var(--muted); }
.bus-panel { padding: 16px clamp(12px, 4vw, 25px) 14px; border: 1px solid #dce5da; border-radius: 16px; background: #f1f4eb; }
.bus-heading { display: flex; align-items: center; justify-content: space-between; margin: 0 2px 14px; color: #71827b; font-size: 11px; font-weight: 800; letter-spacing: .12em; }
.driver { display: grid; width: 35px; height: 27px; place-items: center; border: 1px solid #cbd9cf; border-radius: 8px; color: var(--green); font-size: 17px; }
.seat-grid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 9px 10px; }
.aisle { grid-column: 3; }
.seat { min-width: 0; min-height: 42px; padding: 0 2px; border: 1px solid #91b7a2; border-radius: 9px 9px 6px 6px; background: #fff; color: #246349; font: 700 13px system-ui, sans-serif; cursor: pointer; box-shadow: inset 0 -4px 0 #e1eee5; transition: background .15s, transform .15s, box-shadow .15s; }
.seat:hover:not(:disabled) { transform: translateY(-2px); background: #e7f4eb; }
.seat:active:not(:disabled) { transform: translateY(1px); box-shadow: inset 0 -1px 0 #c5dfce; }
.seat:focus-visible { outline: 3px solid #e18a65; outline-offset: 3px; }
.seat.selected { border-color: var(--green); background: var(--green); color: white; box-shadow: inset 0 -4px 0 #165741; }
.seat.booked { border-color: #e2b1a4; background: #f3ded7; color: #9c5947; box-shadow: inset 0 -4px 0 #eac9be; cursor: not-allowed; text-decoration: line-through; }
.legend { display: flex; flex-wrap: wrap; justify-content: center; gap: 14px; margin-top: 17px; color: #64766f; font-size: 12px; }
.legend span { display: inline-flex; align-items: center; gap: 6px; }
.legend-seat { width: 14px; height: 14px; border: 1px solid #91b7a2; border-radius: 4px; background: white; }
.legend-seat.chosen { border-color: var(--green); background: var(--green); }
.legend-seat.booked { border-color: #e2b1a4; background: #f3ded7; }
.summary { margin-top: 20px; padding: 17px 18px 15px; border-radius: 14px; background: white; }
.summary-head, .price-line, .total-line { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
h2 { margin: 0; font-size: 17px; }
.seat-count { color: var(--green); font-size: 13px; font-weight: 700; }
.chosen-codes { min-height: 23px; margin: 9px 0 13px; color: var(--muted); font-size: 14px; }
.price-line { padding: 7px 0; color: #64766f; font-size: 14px; }
.price-line strong { color: var(--ink); font-variant-numeric: tabular-nums; }
.discount-line strong { color: var(--green); }
.total-line { margin-top: 7px; padding-top: 12px; border-top: 1px solid #e5ebe3; font-weight: 800; }
.total-line strong { color: var(--green); font-size: 22px; font-variant-numeric: tabular-nums; }
.price-note { margin: 8px 0 0; color: #829088; font-size: 12px; }
.status { min-height: 20px; margin: 6px 0 0; color: #a24d3b; font-size: 13px; }
footer { margin-top: 17px; color: #87958d; text-align: center; font-size: 10px; font-weight: 800; letter-spacing: .16em; }
footer span { color: var(--coral); }
@media (max-width: 400px) { body { padding: 12px 10px; } .booking-card { padding: 20px 15px 16px; border-radius: 17px; } .seat-grid { gap: 8px 7px; } .seat { min-height: 40px; font-size: 12px; } .bus-panel { padding-inline: 10px; } .legend { gap: 10px; font-size: 11px; } .summary { padding-inline: 14px; } }

const grid = document.querySelector('#seat-grid');
const booked = new Set(['1B', '3D', '5A', '7C', '9D']);
const selected = new Set();
const codes = ['A', 'B', 'C', 'D'];

for (let row = 1; row <= 10; row += 1) {
  for (let seatIndex = 0; seatIndex < 4; seatIndex += 1) {
    if (seatIndex === 2) {
      const aisle = document.createElement('span');
      aisle.className = 'aisle';
      aisle.setAttribute('aria-hidden', 'true');
      grid.append(aisle);
    }
    const code = `${row}${codes[seatIndex]}`;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'seat';
    button.textContent = code;
    button.dataset.code = code;
    button.setAttribute('aria-label', `Seat ${code}${booked.has(code) ? ', booked' : ''}`);
    if (booked.has(code)) {
      button.disabled = true;
      button.classList.add('booked');
    } else {
      button.setAttribute('aria-pressed', 'false');
      button.addEventListener('click', () => toggleSeat(code, button));
    }
    grid.append(button);
  }
}

function toggleSeat(code, button) {
  const status = document.querySelector('#status');
  status.textContent = '';
  if (selected.has(code)) {
    selected.delete(code);
  } else if (selected.size === 4) {
    status.textContent = 'You can choose up to four seats.';
  } else {
    selected.add(code);
  }
  button.classList.toggle('selected', selected.has(code));
  button.setAttribute('aria-pressed', String(selected.has(code)));
  updateSummary();
}

function updateSummary() {
  const count = selected.size;
  const subtotal = count * 12;
  const discount = count === 4 ? subtotal * 0.1 : 0;
  document.querySelector('#seat-count').textContent = `${count} / 4 seats`;
  document.querySelector('#chosen-codes').textContent = count ? [...selected].join(' · ') : 'No seats selected';
  document.querySelector('#subtotal').textContent = `$${subtotal.toFixed(2)}`;
  document.querySelector('#discount').textContent = `−$${discount.toFixed(2)}`;
  document.querySelector('#discount-line').hidden = discount === 0;
  document.querySelector('#total').textContent = `$${(subtotal - discount).toFixed(2)}`;
}
